<?php
namespace App\Modules\Accompagnement\Controllers;
use App\Http\Controllers\Controller;
use App\Modules\Accompagnement\Services\MissionAccess as Access;
use App\Modules\Identity\Services\Outbox;
use App\Modules\Tenancy\Services\OfficineAccess as Office;
use Illuminate\Http\Request;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\DB;
class MissionVisitController extends Controller {
 private function mission(Request $r,string $id,bool $write=false):array{
  $office=(int)app('tenant.officine_id');Access::lockOffice($r,$office);
  $m=DB::table('support_missions as m')->join('support_requests as q','q.id','=','m.support_request_id')->where('q.officine_id',$office)->where('m.id',$id)->select('m.*')->first();abort_unless($m&&Access::allowed($r,$office,$m->id,$write,$write),404);return [$office,$m];
 }
 private function lead(Request $r,int $office,object $m):bool{return Access::allowed($r,$office,$m->id,true,true);}
 private function visit(object $m,string $id):object{$v=DB::table('support_visits')->where('mission_id',$m->id)->where('id',$id)->lockForUpdate()->first();abort_unless($v,404);return $v;}
 private function planRules():array{return ['title'=>['required','string','max:180','regex:/\S/u'],'mode'=>['required','in:onsite,remote'],'place'=>['required','string','max:500','regex:/\S/u'],'starts_at'=>['required','date','after:now'],'ends_at'=>['required','date','after:starts_at']];}
 private function dates(array $d):array{return ['starts_at'=>Carbon::parse($d['starts_at'])->utc(),'ends_at'=>Carbon::parse($d['ends_at'])->utc()];}
 private function publicEvent(Request $r,object $m,int $office,string $action):void{Access::event($r,$m,$office,$action,'Changement d’intervention ; consulter le planning autorisé.');Outbox::office($office,'mission-visit:'.$m->id.':'.($m->version+1),'Intervention : mise à jour','Le planning ou un compte rendu partagé de votre mission a été mis à jour.');}
 public function index(Request $r,string $id){return DB::transaction(function()use($r,$id){[$office,$m]=$this->mission($r,$id);$lead=$this->lead($r,$office,$m);$q=DB::table('support_visits')->where('mission_id',$m->id);if(!$lead)$q->whereNotNull('published_at');$visits=$q->orderBy('starts_at')->get();$reports=DB::table('support_visit_reports')->whereIn('visit_id',$visits->pluck('id'));if(!$lead)$reports->where('status','shared');$grouped=$reports->orderByDesc('revision')->get()->groupBy('visit_id');foreach($visits as $v){$v->reports=$grouped->get($v->id,collect());$v->starts_at=Carbon::parse($v->starts_at,'UTC')->toIso8601String();$v->ends_at=Carbon::parse($v->ends_at,'UTC')->toIso8601String();foreach($v->reports as $report){$report->actual_starts_at=Carbon::parse($report->actual_starts_at,'UTC')->toIso8601String();$report->actual_ends_at=Carbon::parse($report->actual_ends_at,'UTC')->toIso8601String();}}
 return response()->json(['data'=>$visits,'can_lead'=>$lead,'can_admin'=>$r->attributes->get('officine.is_admin')===true])->header('Cache-Control','no-store');});}
 public function create(Request $r,string $id){$d=$r->validate($this->planRules()+['confirmed'=>['required','accepted'],'request_key'=>['required','string','min:16','max:80','regex:/^[A-Za-z0-9-]+$/']]);return DB::transaction(function()use($r,$id,$d){[$office,$m]=$this->mission($r,$id,true);abort_unless($m->status==='active',409,'Mission non active.');$existing=DB::table('support_visits')->where('mission_id',$m->id)->where('request_key',$d['request_key'])->first();if($existing){$dates=$this->dates($d);abort_unless($existing->created_by===$r->user()->id&&$existing->title===trim($d['title'])&&$existing->mode===$d['mode']&&$existing->place===trim($d['place'])&&$existing->starts_at===$dates['starts_at']->format('Y-m-d H:i:s')&&$existing->ends_at===$dates['ends_at']->format('Y-m-d H:i:s'),409,'Clé déjà utilisée.');return response()->json(['id'=>$existing->id]);}$dates=$this->dates($d);abort_unless($dates['starts_at']->timezone('Africa/Porto-Novo')->toDateString()>=$m->starts_on&&$dates['ends_at']->timezone('Africa/Porto-Novo')->toDateString()<=$m->ends_on,422,'Intervention hors période de mission.');
 $visit=DB::table('support_visits')->insertGetId(['mission_id'=>$m->id,'request_key'=>$d['request_key'],'created_by'=>$r->user()->id,'title'=>trim($d['title']),'mode'=>$d['mode'],'place'=>trim($d['place'])]+$this->dates($d)+['created_at'=>now(),'updated_at'=>now()]);Office::audit($r,$office,'support.visit.draft_created',['request_id'=>$m->support_request_id]);return response()->json(['id'=>$visit],201);});}
 public function transition(Request $r,string $id,string $visitId){$d=$r->validate(['version'=>['required','integer','min:1'],'action'=>['required','in:propose,confirm,cancel,reschedule,complete'],'reason'=>['required','string','max:2000','regex:/\S/u'],'confirmed'=>['required','accepted']]+($r->input('action')==='reschedule'?$this->planRules():[]));
 return DB::transaction(function()use($r,$id,$visitId,$d){[$office,$m]=$this->mission($r,$id);$lead=$this->lead($r,$office,$m);$admin=$r->attributes->get('officine.is_admin')===true;$v=$this->visit($m,$visitId);abort_if(!$v->published_at&&!$lead,404);abort_unless($v->version===(int)$d['version'],409,'Version périmée.');$action=$d['action'];abort_unless(in_array($m->status,['active','suspended'],true),409,'Mission non éligible.');
 if($action==='confirm'){abort_unless($admin,403);abort_unless($m->status==='active'&&$v->status==='proposed'&&Carbon::parse($v->starts_at,'UTC')->isFuture(),409);$status='confirmed';}
 elseif($action==='cancel'){abort_unless($lead||$admin,403);abort_unless(in_array($v->status,['draft','proposed','confirmed'],true),409);$status='cancelled';}
 else{abort_unless($lead,403);abort_unless($m->status==='active',409);
  if($action==='propose'){abort_unless($v->status==='draft'&&Carbon::parse($v->starts_at,'UTC')->isFuture(),409);$status='proposed';}
  elseif($action==='complete'){abort_unless($v->status==='confirmed'&&DB::table('support_visit_reports')->where('visit_id',$v->id)->where('status','shared')->exists(),409,'Un compte rendu partagé est nécessaire.');$status='completed';}
  else{abort_unless(in_array($v->status,['proposed','confirmed'],true),409);$dates=$this->dates($d);abort_unless($dates['starts_at']->timezone('Africa/Porto-Novo')->toDateString()>=$m->starts_on&&$dates['ends_at']->timezone('Africa/Porto-Novo')->toDateString()<=$m->ends_on,422,'Intervention hors période.');DB::table('support_visits')->insert(['mission_id'=>$m->id,'previous_id'=>$v->id,'created_by'=>$r->user()->id,'title'=>trim($d['title']),'mode'=>$d['mode'],'place'=>trim($d['place']),'status'=>'proposed','published_at'=>now()]+$this->dates($d)+['created_at'=>now(),'updated_at'=>now()]);$status='rescheduled';}
 }
 DB::table('support_visits')->where('id',$v->id)->update(['status'=>$status,'published_at'=>$status==='proposed'?now():$v->published_at,'version'=>$v->version+1,'decided_by'=>$r->user()->id,'decision_reason'=>trim($d['reason']),'updated_at'=>now()]);
 if($v->status!=='draft'||$status==='proposed')$this->publicEvent($r,$m,$office,'visit_'.$status);else Office::audit($r,$office,'support.visit.draft_cancelled',['request_id'=>$m->support_request_id]);
 return response()->json(['message'=>'Intervention mise à jour ; les horaires précédents sont conservés.']);});}
 public function report(Request $r,string $id,string $visitId,?string $reportId=null){$d=$r->validate(['visit_version'=>['required','integer','min:1'],'actual_starts_at'=>['required','date','before_or_equal:now'],'actual_ends_at'=>['required','date','after:actual_starts_at','before_or_equal:now'],'attendance'=>['required','string','max:3000','regex:/\S/u'],'activities'=>['required','string','max:8000','regex:/\S/u'],'decisions'=>['required','string','max:5000','regex:/\S/u'],'next_steps'=>['required','string','max:3000','regex:/\S/u'],'confirmed'=>['required','accepted']]+($reportId?['version'=>['required','integer','min:1']]:[]));return DB::transaction(function()use($r,$id,$visitId,$reportId,$d){[$office,$m]=$this->mission($r,$id,true);abort_unless($m->status==='active',409);$v=$this->visit($m,$visitId);abort_unless(in_array($v->status,['confirmed','completed'],true)&&$v->version===(int)$d['visit_version'],409);if($reportId){$existing=DB::table('support_visit_reports')->where('id',$reportId)->where('visit_id',$v->id)->first();abort_unless($existing,404);abort_unless($existing->status==='draft'&&$existing->version===(int)$d['version'],409,'Version figée ou périmée.');DB::table('support_visit_reports')->where('id',$existing->id)->update(['actual_starts_at'=>Carbon::parse($d['actual_starts_at'])->utc(),'actual_ends_at'=>Carbon::parse($d['actual_ends_at'])->utc(),'attendance'=>trim($d['attendance']),'activities'=>trim($d['activities']),'decisions'=>trim($d['decisions']),'next_steps'=>trim($d['next_steps']),'version'=>$existing->version+1,'updated_at'=>now()]);Office::audit($r,$office,'support.visit.report_draft_saved',['request_id'=>$m->support_request_id]);return response()->json(['id'=>$existing->id]);}
 abort_if(DB::table('support_visit_reports')->where('visit_id',$v->id)->whereIn('status',['draft','submitted'])->exists(),409,'Une révision est déjà en préparation.');$revision=(int)DB::table('support_visit_reports')->where('visit_id',$v->id)->max('revision')+1;
 $report=DB::table('support_visit_reports')->insertGetId(['visit_id'=>$v->id,'created_by'=>$r->user()->id,'revision'=>$revision,'actual_starts_at'=>Carbon::parse($d['actual_starts_at'])->utc(),'actual_ends_at'=>Carbon::parse($d['actual_ends_at'])->utc(),'attendance'=>trim($d['attendance']),'activities'=>trim($d['activities']),'decisions'=>trim($d['decisions']),'next_steps'=>trim($d['next_steps']),'created_at'=>now(),'updated_at'=>now()]);Office::audit($r,$office,'support.visit.report_draft_created',['request_id'=>$m->support_request_id]);return response()->json(['id'=>$report],201);});}
 public function reportDecision(Request $r,string $id,string $visitId,string $reportId){$d=$r->validate(['version'=>['required','integer','min:1'],'action'=>['required','in:submit,share'],'confirmed'=>['required','accepted']]);return DB::transaction(function()use($r,$id,$visitId,$reportId,$d){[$office,$m]=$this->mission($r,$id,true);abort_unless($m->status==='active',409);$v=$this->visit($m,$visitId);abort_unless(in_array($v->status,['confirmed','completed'],true),409);$report=DB::table('support_visit_reports')->where('id',$reportId)->where('visit_id',$v->id)->lockForUpdate()->first();abort_unless($report,404);abort_unless($report->version===(int)$d['version']&&$report->status===($d['action']==='submit'?'draft':'submitted'),409);$shared=$d['action']==='share';DB::table('support_visit_reports')->where('id',$report->id)->update(['status'=>$shared?'shared':'submitted','version'=>$report->version+1,$shared?'shared_at':'submitted_at'=>now(),'updated_at'=>now()]);if($shared)$this->publicEvent($r,$m,$office,'visit_report_shared');else Office::audit($r,$office,'support.visit.report_submitted',['request_id'=>$m->support_request_id]);return response()->json(['message'=>'Version figée. Toute correction ultérieure nécessite une nouvelle révision.']);});}
}
